WITH parsed AS (SELECT id, service, host, log_ts, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['trace'] AS trace, context['version'] AS version, CAST((status_code & 2) != 0 AS INT) AS flag_bit2 FROM app_logs WHERE status_code BETWEEN 326 AND 427) SELECT CASE WHEN flag_bit2 >= 1 THEN 'LARGE' ELSE 'SMALL' END AS flag_bit2_tier, DATE_TRUNC('HOUR', log_ts) AS hour_window, SUM(status_code) AS total_status_code, COUNT(*) AS row_count, GROUPING_ID() AS grouping_level FROM parsed GROUP BY CUBE (CASE WHEN flag_bit2 >= 1 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('HOUR', log_ts));
